fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Pre-allocate a vector to hold n elements
    let mut col = Vec::with_capacity(n);
    // Collect the j-th element from each of the n rows
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Prepare the result with m rows (the columns of the original)
    let mut result = Vec::with_capacity(m);
    // For each column index j in 0..m, extract that column
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}

// -- Example usage and test --
fn main() {
    let n = 3;
    let m = 4;
    let matrix: Vec<Vec<i8>> = vec![
        vec![ 1,  2,  3,  4],
        vec![-1, -2, -3, -4],
        vec![10, 20, 30, 40],
    ];
    let transposed = column_stack(matrix, m, n);
    // The result should be a 4x3 matrix:
    // [
    //   [ 1, -1, 10],
    //   [ 2, -2, 20],
    //   [ 3, -3, 30],
    //   [ 4, -4, 40],
    // ]
    for row in &transposed {
        println!("{:?}", row);
    }
}